// In-memory task store.
import { ulid } from "./ulid.js";

const tasks = new Map();

export function createTask(title, now = new Date()) {
	const id = ulid();
	const stamp = now.toISOString();
	const task = { id, title, status: "open", created_at: stamp, updated_at: stamp, deleted_at: null };
	tasks.set(id, task);
	return serializeTask(task);
}

export function updateTask(id, changes, now = new Date()) {
	const task = tasks.get(id);
	if (!task) return undefined;
	Object.assign(task, changes, { updated_at: now.toISOString() });
	return serializeTask(task);
}

export function listTasks() {
	return [...tasks.values()].map(serializeTask);
}

export function getTask(id) {
	const task = tasks.get(id);
	return task && serializeTask(task);
}

export function serializeTask(task) {
	return { ...task, created_at: new Date(task.created_at).toISOString(), updated_at: new Date(task.updated_at).toISOString() };
}

