function trackedTask(id) {
	let reads = 0;
	return {
		task: { id, updated_at: "2026-03-01T10:00:00Z", get title() { reads++; return "cached"; } },
		reads: () => reads,
	};
}

test("serialization cache keys include updated_at and isolates returned objects", () => {
	const { task, reads } = trackedTask("cache-version");
	const first = serializeTask(task);
	first.title = "changed by caller";
	assert.equal(serializeTask(task).title, "cached");
	assert.equal(reads(), 1);
	task.updated_at = "2026-03-01T10:00:01Z";
	assert.equal(serializeTask(task).updated_at, task.updated_at);
	assert.equal(reads(), 2);
});

test("serialization cache evicts the least recently used entry at 500 entries", () => {
	const entries = Array.from({ length: 500 }, (_, i) => trackedTask(`lru-${i}`));
	for (const { task } of entries) serializeTask(task);
	serializeTask(entries[0].task);
	serializeTask(trackedTask("lru-overflow").task);
	serializeTask(entries[0].task);
	assert.equal(entries[0].reads(), 1);
	serializeTask(entries[1].task);
	assert.equal(entries[1].reads(), 2);
});

test("PATCH invalidates cached tasks even within the same second", () => {
	const now = new Date("2026-03-01T10:00:00Z");
	const task = createTask("before", now);
	const updated = updateTask(task.id, { title: "after", status: "done" }, now);
	assert.equal(updated.updated_at, task.updated_at);
	assert.equal(updated.title, "after");
	assert.equal(getTask(task.id).status, "done");
	assert.deepEqual(listTasks().find(({ id }) => id === task.id), updated);
});

