import { createTask, getTask, listTasks, updateTask } from "../store.js";

export function handle(method, url, body) {
	const parts = url.pathname.split("/").filter(Boolean);
	if (parts[0] !== "tasks") return { status: 404, body: { message: "not found" } };
	if (method === "GET" && parts.length === 1) {
		const limit = Number(url.searchParams.get("limit") ?? 25);
		return { status: 200, body: { items: listTasks().slice(0, limit) } };
	}
	if (method === "POST" && parts.length === 1) {
		const { title } = JSON.parse(body || "{}");
		if (!title) return { status: 400, body: { message: "title required" } };
		return { status: 201, body: createTask(title) };
	}
	if (method === "GET") {
		const task = getTask(parts[1]);
		return task ? { status: 200, body: task } : { status: 404, body: { message: "not found" } };
	}
	if (method === "PATCH") {
		const task = updateTask(parts[1], JSON.parse(body || "{}"));
		return task ? { status: 200, body: task } : { status: 404, body: { message: "not found" } };
	}
	return { status: 405, body: { message: "method not allowed" } };
}

