import { createTask, getTask, listTasks, updateTask } from "../store.js";

export function handle(method, url, body) {
	const parts = url.pathname.split("/").filter(Boolean);
	if (parts[0] !== "tasks") return error(404, "not_found", "not found");
	if (method === "GET" && parts.length === 1) return list(url);
	if (method === "POST" && parts.length === 1) return create(body);
	if (method === "GET") {
		const task = getTask(parts[1]);
		return task ? { status: 200, body: task } : error(404, "not_found", "not found");
	}
	if (method === "PATCH") return patch(parts[1], body);
	return error(405, "method_not_allowed", "method not allowed");
}

function error(status, code, message) {
	return { status, body: { error: { code, message } } };
}

function list(url) {
	const raw = url.searchParams.get("limit") ?? "25";
	const limit = Number(raw);
	if (!/^\d+$/.test(raw) || !Number.isInteger(limit) || limit < 1 || limit > 100) {
		return error(400, "invalid_limit", "limit must be an integer between 1 and 100");
	}
	return { status: 200, body: { items: listTasks().slice(0, limit) } };
}

function parseBody(body) {
	try {
		const value = JSON.parse(body || "{}");
		if (value === null || typeof value !== "object" || Array.isArray(value)) {
			return { failure: error(400, "invalid_body", "body must be a JSON object") };
		}
		return { value };
	} catch {
		return { failure: error(400, "invalid_json", "malformed JSON") };
	}
}

function create(body) {
	const { value, failure } = parseBody(body);
	if (failure) return failure;
	if (typeof value.title !== "string" || !value.title.trim()) {
		return error(400, "invalid_title", "title must be a non-empty string");
	}
	return { status: 201, body: createTask(value.title) };
}

function patch(id, body) {
	const { value, failure } = parseBody(body);
	if (failure) return failure;
	const task = updateTask(id, value);
	return task ? { status: 200, body: task } : error(404, "not_found", "not found");
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { handle } from "../src/routes/tasks.js";

function request(method, path, body) {
	return handle(method, new URL(path, "http://localhost"), body);
}

function expectError(response, status, code) {
	assert.equal(response.status, status);
	assert.deepEqual(Object.keys(response.body), ["error"]);
	assert.deepEqual(Object.keys(response.body.error).sort(), ["code", "message"]);
	assert.equal(response.body.error.code, code);
	assert.equal(typeof response.body.error.message, "string");
	assert.ok(response.body.error.message.length);
}

test("task route errors use stable error envelopes", () => {
	expectError(request("GET", "/unknown"), 404, "not_found");
	expectError(request("GET", "/tasks/missing"), 404, "not_found");
	expectError(request("PATCH", "/tasks/missing", "{}"), 404, "not_found");
	expectError(request("DELETE", "/tasks/missing"), 405, "method_not_allowed");
	for (const body of [undefined, "{}", '{"title":""}', '{"title":42}']) {
		expectError(request("POST", "/tasks", body), 400, "invalid_title");
	}
});

test("invalid JSON and non-object bodies use error envelopes", () => {
	for (const method of ["POST", "PATCH"]) {
		const path = method === "POST" ? "/tasks" : "/tasks/missing";
		expectError(request(method, path, "{"), 400, "invalid_json");
		for (const body of ["null", "[]", "42", '"text"']) {
			expectError(request(method, path, body), 400, "invalid_body");
		}
	}
});

test("invalid limits return 400 instead of being clamped", () => {
	for (const limit of ["", "0", "-1", "101", "1.5", "NaN", "Infinity", "abc"]) {
		expectError(request("GET", `/tasks?limit=${limit}`), 400, "invalid_limit");
	}
	for (const path of ["/tasks", "/tasks?limit=1", "/tasks?limit=100"]) {
		assert.equal(request("GET", path).status, 200);
	}
});

