	const created = request("POST", "/tasks", '{"title":"route regression"}');
	assert.equal(created.status, 201);
	const path = `/tasks/${created.body.id}`;
	assert.deepEqual(request("GET", path).body, created.body);
	const patched = request("PATCH", path, '{"status":"done"}');
	assert.equal(patched.status, 200);
	assert.equal(patched.body.status, "done");
});

