test("soft delete retains task data and stamps deletion in UTC seconds", () => {
	const task = createTask("retained task", new Date("2026-03-01T10:00:00Z"));
	const deleted = deleteTask(task.id, new Date("2026-03-02T09:00:00.123Z"));
	assert.equal(deleted.deleted_at, "2026-03-02T09:00:00Z");
	assert.equal(deleted.updated_at, deleted.deleted_at);
	assert.equal(deleted.created_at, task.created_at);
	assert.equal(deleted.title, task.title);
	assert.equal(getTask(task.id), undefined);
	assert.ok(!listTasks().some(({ id }) => id === task.id));
	assert.equal(deleteTask(task.id), undefined);
	assert.equal(updateTask(task.id, { deleted_at: null }), undefined);
	assert.equal(deleteTask("missing"), undefined);
});

