test("PATCH rejects protected fields and invalid values without mutating tasks", () => {
	const task = request("POST", "/tasks", '{"title":"protected"}').body;
	const path = `/tasks/${task.id}`;
	for (const field of ["id", "created_at", "updated_at", "deleted_at", "extra", "__proto__"]) {
		expectError(request("PATCH", path, JSON.stringify({ [field]: "changed" })), 400, "invalid_field");
	}
	for (const title of ["", "  ", null, 42, {}]) {
		expectError(request("PATCH", path, JSON.stringify({ title })), 400, "invalid_title");
	}
	for (const status of ["closed", "", null, 42]) {
		expectError(request("PATCH", path, JSON.stringify({ status })), 400, "invalid_status");
	}
	assert.deepEqual(request("GET", path).body, task);
});

test("cursor pagination traverses filtered tasks without duplicates", () => {
	const expected = [];
	for (let i = 0; i < 3; i++) {
		const task = request("POST", "/tasks", '{"title":"cursor task"}').body;
		request("PATCH", `/tasks/${task.id}`, '{"status":"done"}');
		expected.push(task.id);
	}
	const seen = [];
	let cursor = null;
	do {
		const suffix = cursor === null ? "" : `&cursor=${encodeURIComponent(cursor)}`;
		const page = request("GET", `/tasks?status=done&limit=1${suffix}`);
		assert.equal(page.status, 200);
		assert.ok(page.body.items.length <= 1);
		seen.push(...page.body.items.map(task => task.id));
		cursor = page.body.next_cursor;
		assert.ok(seen.length < 100, "pagination must terminate");
	} while (cursor !== null);
	assert.equal(new Set(seen).size, seen.length);
	for (const id of expected) assert.ok(seen.includes(id));
	const first = request("GET", "/tasks?status=done&limit=1");
	expectError(request("GET", `/tasks?status=open&cursor=${first.body.next_cursor}`), 400, "invalid_cursor");
	for (const raw of ["", "garbage", "e30", "bnVsbA"]) {
		expectError(request("GET", `/tasks?cursor=${raw}`), 400, "invalid_cursor");
	}
});

